use std::collections::BTreeMap;

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Observation {
    pub outcome: i64,
    pub features: Vec<i64>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ModelError {
    EmptyName,
    EmptyFeatures,
    ArityMismatch,
    UnknownModel,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ObservationStore {
    models: BTreeMap<String, Vec<Observation>>,
}

impl ObservationStore {
    pub fn new() -> ObservationStore {
        ObservationStore {
            models: BTreeMap::new(),
        }
    }

    pub fn update(
        &mut self,
        name: &str,
        observations: Vec<Observation>,
    ) -> Result<(), ModelError> {
        if name.is_empty() {
            return Err(ModelError::EmptyName);
        }
        if observations.is_empty() {
            return Ok(());
        }
        if observations.iter().any(|item| item.features.is_empty()) {
            return Err(ModelError::EmptyFeatures);
        }

        let arity = self
            .models
            .get(name)
            .and_then(|items| items.first())
            .map(|item| item.features.len())
            .unwrap_or(observations[0].features.len());

        if observations
            .iter()
            .any(|item| item.features.len() != arity)
        {
            return Err(ModelError::ArityMismatch);
        }

        self.models
            .entry(name.to_string())
            .or_default()
            .extend(observations);
        Ok(())
    }

    pub fn predict(
        &self,
        name: &str,
        queries: &[Vec<i64>],
    ) -> Result<Vec<i64>, ModelError> {
        if name.is_empty() {
            return Err(ModelError::EmptyName);
        }

        let observations = self.models.get(name).ok_or(ModelError::UnknownModel)?;
        let arity = observations[0].features.len();

        if queries.iter().any(|query| query.is_empty()) {
            return Err(ModelError::EmptyFeatures);
        }
        if queries.iter().any(|query| query.len() != arity) {
            return Err(ModelError::ArityMismatch);
        }

        Ok(queries
            .iter()
            .map(|query| {
                let mut matched_sum = 0_i128;
                let mut matched_count = 0_i128;

                for observation in observations {
                    if observation.features == *query {
                        matched_sum += observation.outcome as i128;
                        matched_count += 1;
                    }
                }

                if matched_count != 0 {
                    (matched_sum / matched_count) as i64
                } else {
                    let total: i128 = observations
                        .iter()
                        .map(|observation| observation.outcome as i128)
                        .sum();
                    (total / observations.len() as i128) as i64
                }
            })
            .collect())
    }
}

pub fn new() -> ObservationStore {
    ObservationStore::new()
}
